CVar*Register(const char*n,const char*h,const char*v,bool save=true){if(auto*found=CVar::LookupRegistered(n))return found;return CVar::Register(n,h,save?1:0,v,nullptr,CATEGORY_GRAPHICS,false,nullptr,false);}
void StatusValue(const char*n,const char*v){auto*c=CVar::LookupRegistered(n);if(!c)c=Register(n,"Lumen native status",v,false);if(c&&(!c->m_stringValue.m_str||std::strcmp(c->m_stringValue.m_str,v))){c->SetReadOnly(false);c->InternalSet(v,true,false,false,false);}if(c)c->SetReadOnly(true);}
float Value(const char*n,float fallback){auto*c=CVar::LookupRegistered(n);return c&&std::isfinite(c->m_floatValue)?c->m_floatValue:fallback;}
void Publish(){const auto&a=suite.Available();StatusValue("hdLvReady",a.backend?"1":"0");struct P{const char*n;bool b;};P p[]={{"Lamps",a.lamps},{"Fog",a.fog},{"Halos",a.halos},{"Ambiance",a.ambiance},{"Spells",a.spells},{"Shafts",a.shafts},{"Memory",a.memory},{"Terrain",a.terrain},{"Blur",a.blur}};for(auto&v:p){char key[64];std::snprintf(key,sizeof key,"hdLv%sReady",v.n);StatusValue(key,v.b?"1":"0");}StatusValue("hdLvInfo",suite.Status());StatusValue("hdLvLampCubeInfo",suite.CubeInfo()); /* Claude LV22 */{const auto&s=suite.SpellStats();char t[240];std::snprintf(t,sizeof t,"lumieres de sorts %zu, groupes %d, cellules %d, sans couleur %d, ecartes meteo %d, pluie %d, sprites %d",suite.SpellLightCount(),s.clusters,s.cells,s.colourless,s.suppressedCells,s.fallingDropped,s.sprites);StatusValue("hdLvSpellInfo",t);
 // Claude L9: spell light diagnostic written to Logs\\lumen-sorts.txt (only while spells are asked), throttled.
 static double lastLog=-100;static int lines=0;static unsigned lastMeasured=0;
 const double now=std::chrono::duration<double>(std::chrono::steady_clock::now().time_since_epoch()).count();
 const bool active=suite.SpellLightCount()>0||s.clusters>0||s.cells>0;
 // REL1 (2026-11-06): journal off by default for players; /console hdLvSpellLog 1 turns it on.
 static CVar*spellLog=Register("hdLvSpellLog","Lumen: spell light journals Logs\\lumen-sorts.txt and lumen-projectiles.txt, 1 on / 0 off (default 0)","0");(void)spellLog;
 if(Value("hdLvSpellLog",0)!=0&&Value("hdLvSpells",0)!=0&&lines<4000&&(now-lastLog>(active?0.2:5.0))){
  if(std::FILE*f=std::fopen("Logs\\lumen-sorts.txt","a")){
   std::fprintf(f,"t %.1f etat \"%s\" mesures %u (+%u) sautees %u lumieres %zu groupes %d cellules %d sans_couleur %d flammes %d pluie %d sprites %d seuil %.2f fond %.2f anneau %d\n",now,suite.Status(),suite.SpellMeasurements(),suite.SpellMeasurements()-lastMeasured,suite.SpellSkipped(),suite.SpellLightCount(),s.clusters,s.cells,s.colourless,s.suppressedCells,s.fallingDropped,s.sprites,s.least,s.background,s.ringCells);
   for(const auto&e:suite.SpellLamps())std::fprintf(f,"   sort pos %.2f %.2f %.2f couleur %.2f %.2f %.2f intensite %.2f portee %.1f\n",e.position[0],e.position[1],e.position[2],e.colour[0],e.colour[1],e.colour[2],e.intensity,e.surfaceReach);
   std::fclose(f);++lines;lastLog=now;lastMeasured=suite.SpellMeasurements();}}
 // Claude L17: read-only fog journal, Logs\\lumen-brume.txt, once a second while hdLvFog is on (hdLvFogLog 0 stops it).
 // It changes nothing on screen: it writes what the fog received (For Ever layers or the game's own fog) and the sun light it ends with.
 {static double lastFog=-100;static int fogLines=0;static CVar*fogLog=Register("hdLvFogLog","Lumen: fog journal Logs\\lumen-brume.txt, 1 on / 0 off (default 0, Claude DEF1)","0");(void)fogLog;{static bool hdDef1Once=false;if(!hdDef1Once){hdDef1Once=true;if(fogLog&&fogLog->m_intValue!=0)fogLog->InternalSet("0",true,false,false,false);}} // Claude DEF1: diagnostic journal off at every start (a test never leaves it on)
  if(Value("hdLvFog",0)!=0&&Value("hdLvFogLog",0)!=0&&fogLines<6000&&now-lastFog>=1.0){
   if(std::FILE*f=std::fopen("Logs\\lumen-brume.txt","a")){
    const auto&n=suite.NativeUsed();const auto&in=suite.FrameUsed();const auto&p=suite.FogUsed();const auto&cfg=suite.ConfigUsed();
    auto lum=[](const float*c){return .2126f*c[0]+.7152f*c[1]+.0722f*c[2];};
    float sun=0,amb=0;
    for(int i=0;i<Source::kFogLayers;++i){const auto&l=p.layers[i];float path=std::max(0.f,150.f-l.start);if(l.endDistance<l.start)path=0;
     float h=std::clamp(std::exp((l.upperHeight-p.referenceZ)*l.upperFalloff),0.f,1.f)*std::clamp(std::exp((p.referenceZ-l.lowerHeight)*l.lowerFalloff),0.f,1.f);
     float op=1.f-std::exp(-std::max(l.density,0.f)*h*path);if(!std::isfinite(op))op=0;sun+=lum(l.diffuse)*op;amb+=lum(l.emissive)*op;}
    const char*place=n.journalPlace[0]?n.journalPlace:"(lieu inconnu)";
    std::fprintf(f,"t %.1f heure %.2f %s | source %s | soleil visible %.2f lune %d | reglages SunScatter %.2f ViewLight %.2f AntiGlare %.2f ScatterNuit %.2f Aube %.2f Jour %.2f Soir %.2f | LUMIERE SOLEIL PRES %.4f AMBIANTE PRES %.4f\n",
     now,24.0*(in.dayFraction-std::floor(in.dayFraction)),place,n.hasAuthored?"ForEver":"jeu 3.3.5 (pas de donnees ForEver)",p.lightVisibility,in.lightIsMoon?1:0,
     cfg.sunScatter,cfg.viewLight,cfg.antiGlare,cfg.scatterNight,cfg.scatterDawn,cfg.scatterDay,cfg.scatterDusk,sun,amb);
    if(n.hasAuthored)for(int i=0;i<n.authored.layerCount;++i){const auto&a=n.authored.layers[i];
     std::fprintf(f,"   ForEver recu couche %d debut %.0f densite %.5f intensite %.2f g %.2f couleur soleil %.2f %.2f %.2f\n",i,a.start,a.density,a.intensity,a.g,a.diffuse[0],a.diffuse[1],a.diffuse[2]);}
    for(int i=0;i<Source::kFogLayers;++i){const auto&l=p.layers[i];
     std::fprintf(f,"   final couche %d debut %.0f densite %.6f g %.2f soleil %.4f %.4f %.4f ambiant %.4f %.4f %.4f\n",i,l.start,l.density,l.g,l.diffuse[0],l.diffuse[1],l.diffuse[2],l.emissive[0],l.emissive[1],l.emissive[2]);}
    std::fclose(f);++fogLines;lastFog=now;}}}
 }}
// Claude G1 2026-11-05: Logs\\lumen-gpu.txt every 2 s while hdLvGpuTimes is 1: GPU ms per frame of each Lumen kernel. Measure only, off at every start.
void GpuTimesLog(){
 static CVar*v=nullptr;if(!v){v=Register("hdLvGpuTimes","Lumen: 1 = GPU time of each fog/lamp kernel in Logs\\lumen-gpu.txt every 2 s (measure only, off at every start)","0");if(v&&v->m_intValue!=0)v->InternalSet("0",true,false,false,false);}
 static const char*names[]={"LampSurfaces","LampVisibility","LampHalos","LampBlur","FogTemporal","EdgeOccluders","MemoryKeep","EffectGather","EffectReduce","Fog1Memory0","Fog1Memory1","Fog2Memory0","Fog2Memory1","Fog3Memory0","Fog3Memory1","MemorySeed","MemoryResolve","MemoryScatter","MemoryRealign","MemoryFill","DepthCopy","SceneComposite","WaterLamps","LampSurfacesOpt","LampBlurOpt","LampListes16","WaterLampsOpt","EffectGatherOpt","Fog1Fast","Fog2Fast","Fog3Fast"};
 static_assert(sizeof names/sizeof names[0]==size_t(Kernel::Count),"one name per kernel");
 const bool on=v&&v->m_intValue!=0;static double last=-1;const double now=std::chrono::duration<double>(std::chrono::steady_clock::now().time_since_epoch()).count();
 auto clear=[](){for(size_t i=0;i<size_t(Kernel::Count);++i){GpuTiming::ms[i]=0;GpuTiming::runs[i]=0;}GpuTiming::frames=GpuTiming::barriers=GpuTiming::dispatches=GpuTiming::surfacesSkipped=0;};
 if(on!=GpuTiming::on){GpuTiming::on=on;clear();last=now;return;}
 if(!on||now-last<2.0)return;last=now;
 const double frames=double(GpuTiming::frames);
 if(frames>0)if(std::FILE*f=std::fopen("Logs\\lumen-gpu.txt","a")){
  double total=0;for(size_t i=0;i<size_t(Kernel::Count);++i)total+=GpuTiming::ms[i];
  std::fprintf(f,"t %.1f images %.0f | passes %.3f ms/image | dispatchs %.1f/image | barrieres %.1f/image | lampes de surface sautees %.0f %%\n",now,frames,total/frames,GpuTiming::dispatches/frames,GpuTiming::barriers/frames,100.0*GpuTiming::surfacesSkipped/frames);
  for(size_t i=0;i<size_t(Kernel::Count);++i)if(GpuTiming::runs[i])std::fprintf(f,"   %-15s %.3f ms/image  %.2f fois/image  %.3f ms/fois\n",names[i],GpuTiming::ms[i]/frames,GpuTiming::runs[i]/frames,GpuTiming::ms[i]/GpuTiming::runs[i]);
  std::fclose(f);}
 else if(!GpuTiming::available)if(std::FILE*f=std::fopen("Logs\\lumen-gpu.txt","a")){std::fprintf(f,"t %.1f pas d'horodatage GPU sur cette file\n",now);std::fclose(f);}
 clear();
}
