 {auto*v=Register("hdLvLampView","Lumen (Claude LV11/LV16): 1 = diagnostic view of the lamp light on the surfaces: magenta = G-buffer class not lit by Lumenveil, blue = depth tag or normal rejected, dark = no lamp light here, red = lamp light but already saturated, green = light added (brighter = more); 2 = the base light the G-buffer gives each surface (what the lamp gain depends on); 3 = yellow where LampSurfaces judged the pixel thin (light floor 60 %, no lamp shadow); 4 = the lamp light alone (what LampSurfaces + blur add, grey scale); 5 = the surface normal Lumenveil uses (G-buffer normal turned to the camera as LampSurfaces does; grey = no G-buffer normal); 6 = why a pixel gets lamp light or not (red = lamps within reach, green = lamps skipped for its class, blue = how much the surface faces them; set hdLvBlur 0 and hdLvTiles 0 for it); not saved, off at every start","0",false);if(v&&v->m_intValue!=0)v->InternalSet("0",true,false,false,false);}
